+// ── HEADLESS ──────────────────────────────────────────
+
+{ch:'headless',type:'mc',
+ q:'How do the GUI tests render with no <code>DISPLAY</code> on the EC2 runner?',
+ opts:[
+   {t:'Top-level conftest sets <code>QT_QPA_PLATFORM=offscreen</code> before Qt import; <code>pytest-xvfb</code> starts a virtual framebuffer automatically.',correct:true,why:'Correct. Offscreen rendering needs no X server, and pytest-xvfb (in requirements-dev.txt) spins up xvfb on EC2 — no manual DISPLAY or xvfb-run prefix.'},
+   {t:'Each test is launched with an explicit <code>xvfb-run</code> wrapper in the CI script.',correct:false,why:'You explicitly do NOT prefix with xvfb-run. pytest-xvfb handles it, and offscreen needs no X at all.'},
+   {t:'Qt is mocked, so no real rendering happens.',correct:false,why:'Qt really renders, just to an offscreen surface. Real pixels are essential for the golden comparison to mean anything.'},
+   {t:'A real X server is required; the runner runs a lightweight desktop.',correct:false,why:'No real display/desktop is needed. Offscreen + pytest-xvfb cover it headlessly.'},
+ ]},
+
+{ch:'headless',type:'wr',
+ q:'Why is <code>QT_QPA_PLATFORM=offscreen</code> set in the top-level <code>tests/conftest.py</code> instead of in the <code>qapp</code> fixture?',
+ concepts:[
+   {label:'Qt reads the var at import time',terms:['import','import time','before','reads','plugin']},
+   {label:'fixture runs after Qt already imported',terms:['fixture','too late','already imported','after']},
+   {label:'must set before any Qt import',terms:['before any qt','before qt import','ordering','order']},
