+"""Visual + interaction tests for the canvas.
+
+``test_canvas_with_psu_block`` is a real interaction test: it clicks the
+"Power Supply" button via ``qtbot.mouseClick`` and waits for the block to
+appear with ``qtbot.waitUntil`` (never ``time.sleep``), exactly as a user
+would add a block.
+
+Note on what "the device palette" is: the GUI exposes block-adding in two
+places — a toolbar with one ``QPushButton`` per block type, and a dockable
+library list (double-click). These tests drive the toolbar button.
+
+The canvas auto-places a new block at the far top-left of the (large) scene,
+which is off-screen in the default view, so the test calls the app's own
+``fit_all()`` to bring the block into view before screenshotting — otherwise
+the golden would show an empty viewport.
+"""
+from __future__ import annotations
+
+from PyQt6.QtCore import Qt
+from PyQt6.QtWidgets import QPushButton
+
+from silmulator.gui.main_window import MainWindow
+
+from .conftest import compare_screenshot
+
+# Fixed window size so the canvas viewport geometry — and therefore the
+# background grid and fitted block — render identically on every machine.
+WINDOW_WIDTH = 1000
+WINDOW_HEIGHT = 700
+WAIT_TIMEOUT_MS = 3000
+
+
+def _find_palette_button(window: MainWindow, label: str) -> QPushButton:
+    """Return the toolbar button that adds the given block type."""
+    for button in window.findChildren(QPushButton):
+        if button.text() == label:
+            return button
+    raise AssertionError(f"no palette button labelled {label!r}")
+
+
+def test_canvas_empty_state(qapp, qtbot):
+    """A fresh canvas shows the empty grid and nothing else."""
+    window = MainWindow()
+    window.resize(WINDOW_WIDTH, WINDOW_HEIGHT)
+    qtbot.addWidget(window)
+    window.show()
+    qtbot.waitExposed(window, timeout=5000)
+    qapp.processEvents()
+    assert window.canvas.blocks == []
+    compare_screenshot(window.canvas_view, "canvas_empty")
+
+
+def test_canvas_with_psu_block(qapp, qtbot):
+    """Clicking the PSU palette button adds a Power Supply block to the canvas."""
+    window = MainWindow()
+    window.resize(WINDOW_WIDTH, WINDOW_HEIGHT)
+    qtbot.addWidget(window)
+    window.show()
+    qtbot.waitExposed(window, timeout=5000)
+
+    psu_button = _find_palette_button(window, "Power Supply")
+    qtbot.mouseClick(psu_button, Qt.MouseButton.LeftButton)
+
+    qtbot.waitUntil(lambda: len(window.canvas.blocks) == 1, timeout=WAIT_TIMEOUT_MS)
+
+    # The block is auto-placed off-screen; fit the view so it is visible in
+    # the screenshot (this is the app's own "show all" action).
+    window.canvas_view.fit_all()
+    qapp.processEvents()
+
+    assert window.canvas.blocks[0].device_type == "Power Supply"
+    compare_screenshot(window.canvas_view, "canvas_with_psu_block")


