+.r-btn.secondary:hover{border-color:var(--blue);color:var(--blue)}
+</style>
+</head>
+<body>
+
+<!-- ══ START ══ -->
+<div id="start-screen">
+  <div class="logo">DRILL / 0008</div>
+  <h1>Visual Regression Testing</h1>
+  <p class="sub">Active recall drill — compare_screenshot, capture targets, determinism, golden workflow, headless</p>
+
+  <div class="chips" id="channel-chips">
+    <span class="chip all-chip on" data-ch="all">all channels</span>
+    <span class="chip on" data-ch="helper">compare_screenshot</span>
+    <span class="chip on" data-ch="capture">capture targets</span>
+    <span class="chip on" data-ch="determinism">determinism</span>
+    <span class="chip on" data-ch="workflow">golden workflow</span>
+    <span class="chip on" data-ch="headless">headless</span>
+    <span class="chip on" data-ch="traps">traps &amp; gotchas</span>
+  </div>
+
+  <div class="opt-row">
+    <div class="toggle on" id="shuffle-tog" onclick="toggleShuffle()"></div>
+    <span class="toggle-lbl" onclick="toggleShuffle()">Shuffle questions</span>
+  </div>
+
+  <button class="begin-btn" id="begin-btn" onclick="begin()">Begin drill</button>
+  <p class="count-note" id="count-note">18 questions selected</p>
+</div>
+
+<!-- ══ DRILL ══ -->
+<div id="drill-screen" class="hidden">
+  <div class="drill-header">
+    <span class="prog-text" id="prog-text">Q 1 / 18</span>
+    <div class="prog-bar"><div class="prog-fill" id="prog-fill" style="width:0%"></div></div>
+  </div>
+
+  <div class="q-meta" id="q-meta"></div>
+  <div class="q-text" id="q-text"></div>
+  <div id="q-body"></div>
+
+  <div class="nav-row">
+    <button class="nav-btn" id="prev-btn" onclick="go(-1)" disabled>← prev</button>
+    <button class="nav-btn" id="next-btn" onclick="go(1)">next →</button>
+  </div>
+</div>
+
+<!-- ══ RESULTS ══ -->
+<div id="results-screen" class="hidden">
+  <div class="logo">DRILL / 0008 — RESULTS</div>
+  <h2>Session complete</h2>
+  <div class="score-grid">
+    <div class="sc-box"><div class="sc-big" id="mc-score">-</div><div class="sc-lbl">MC correct</div></div>
+    <div class="sc-box"><div class="sc-big" id="wr-score">-</div><div class="sc-lbl">Written: knew it</div></div>
+  </div>
+  <div class="miss-list" id="miss-list"></div>
+  <div class="results-btns">
+    <button class="r-btn primary" onclick="reviewMissed()">Review missed only</button>
+    <button class="r-btn secondary" onclick="restart()">Restart from scratch</button>
+  </div>
+</div>
+
+<script>
+// ══════════════════════════════════════════════════════
+// QUESTION BANK
+// ══════════════════════════════════════════════════════
+const BANK = [
+
+// ── compare_screenshot HELPER ─────────────────────────
+
+{ch:'helper',type:'mc',
+ q:'What are the four stages of <code>compare_screenshot</code> on a run where the golden already exists?',
+ opts:[
+   {t:'capture → convert → compare → threshold.',correct:true,why:'Correct. _capture(target) → QImage; _qimage_to_pil() → PIL RGB; ImageChops.difference + RMS; then fail if rms > threshold.'},
+   {t:'show → grab → save → assert.',correct:false,why:'There is no show/grab/save pipeline here. Saving only happens on first run or update. The real flow is capture, convert, compare, threshold.'},
+   {t:'render → resize → hash → compare hashes.',correct:false,why:'No hashing or resizing is done. It computes an RMS pixel difference, and it asserts sizes are equal rather than resizing.'},
+   {t:'load golden → diff → update golden → return.',correct:false,why:'It does not update the golden on a normal run — only on first-run or when update_golden is set. The normal flow ends with a pass/fail on the threshold.'},
+ ]},
+
+{ch:'helper',type:'mc',
+ q:`What metric does <code>compare_screenshot</code> use to decide pass/fail?
+
+<pre class="snippet">diff = <span class="cls">ImageChops</span>.<span class="fn">difference</span>(actual, golden)
+rms = <span class="fn">float</span>(np.<span class="fn">sqrt</span>(np.<span class="fn">mean</span>(np.<span class="fn">asarray</span>(diff, dtype=<span class="fn">float</span>) ** <span class="num">2</span>)))</pre>`,
+ opts:[
+   {t:'Root-mean-square of the per-pixel, per-channel difference; fail if <code>rms &gt; threshold</code>.',correct:true,why:'Correct. sqrt(mean(diff**2)) over every channel of every pixel — a single scalar compared against the threshold.'},
+   {t:'Count of pixels that differ at all; fail if more than <code>threshold</code> pixels changed.',correct:false,why:'It is not a pixel count. It is the RMS magnitude of the differences averaged across the whole image.'},
+   {t:'Maximum single-pixel difference; fail if any pixel exceeds <code>threshold</code>.',correct:false,why:'It is the mean (via RMS), not the max. A single hot pixel barely moves the RMS — it is an average-magnitude metric.'},
+   {t:'Structural similarity index (SSIM); fail below <code>threshold</code>.',correct:false,why:'No SSIM is used. The code computes a plain RMS over ImageChops.difference.'},
+ ]},
+
+{ch:'helper',type:'wr',
+ q:'Describe exactly what <code>compare_screenshot</code> does on the FIRST run of a brand-new test (no golden yet). Quote the branch condition that controls it.',
+ concepts:[
+   {label:'branch: update_golden or not exists()',terms:['not golden_path.exists','not exists','update_golden or','exists()']},
+   {label:'saves the render as the golden',terms:['save','actual.save','saved','creates']},
+   {label:'returns / test passes',terms:['return','passes','pass']},
+   {label:'commit the golden afterward',terms:['commit','git add','committed']},
+ ],
+ model:'On the first run, golden_path does not exist, so the branch `if update_golden or not golden_path.exists():` is taken. It mkdir()s GOLDEN_DIR, saves the captured render via actual.save(golden_path), prints "Golden image saved", and returns — so the test passes without any comparison. You then review and git add the new golden so later runs compare against it.',
+},
+
+{ch:'helper',type:'wr',
+ q:'When a comparison fails (rms over threshold), what two diagnostic files are written and where, and what does the AssertionError message tell you to do?',
+ concepts:[
+   {label:'actual.png written to diffs/',terms:['actual','_actual','diffs','diff_dir']},
+   {label:'diff.png amplified 10x',terms:['diff','amplified','10x','* 10','x10']},
+   {label:'paths printed in the error',terms:['path','golden','printed','message']},
+   {label:'cp actual to golden + git add to accept',terms:['cp','git add','accept','copy']},
+ ],
+ model:'Two files go into tests/visual/diffs/: <name>_actual.png (what this run rendered) and <name>_diff.png (the per-pixel difference amplified 10x so it is visible). The AssertionError prints the golden, actual, and diff paths plus the RMS, and gives the exact command to accept an intentional change: cp <actual> <golden> && git add <golden>.',
+},
+
+{ch:'helper',type:'mc',
+ q:'Why does <code>_qimage_to_pil</code> convert the QImage to <code>Format_RGBA8888</code> before wrapping it in a NumPy array?',
+ opts:[
+   {t:'It gives a known channel order and a tightly packed buffer (no row padding), so the same code works regardless of the platform native pixmap format.',correct:true,why:'Correct — that is exactly the docstring rationale: predictable RGBA layout with no per-row padding, then reshaped to (h, w, 4) and converted to RGB.'},
+   {t:'RGBA8888 compresses the image so the NumPy array uses less memory.',correct:false,why:'It is not compression — it is a fixed uncompressed channel layout. The point is a predictable, padding-free byte buffer.'},
+   {t:'PIL can only read RGBA8888 buffers.',correct:false,why:'PIL reads many formats. The conversion is about a consistent, packed byte layout from Qt, not a PIL limitation.'},
+   {t:'It strips the alpha channel so the comparison ignores transparency.',correct:false,why:'RGBA8888 keeps alpha; alpha is dropped later by .convert("RGB"). The format conversion is about buffer layout, not alpha.'},
+ ]},
+
+// ── CAPTURE TARGETS ───────────────────────────────────
+
+{ch:'capture',type:'mc',
+ q:`Given this <code>_capture</code>, what happens if you pass it a plain <code>str</code>?
+
+<pre class="snippet"><span class="kw">def</span> <span class="fn">_capture</span>(target) -> <span class="cls">QImage</span>:
+    <span class="kw">if</span> <span class="fn">isinstance</span>(target, <span class="cls">QWidget</span>):
+        <span class="kw">return</span> target.<span class="fn">grab</span>().<span class="fn">toImage</span>()
+    <span class="kw">if</span> <span class="fn">isinstance</span>(target, <span class="cls">QGraphicsItem</span>):
+        <span class="kw">return</span> <span class="fn">_capture_graphics_item</span>(target)
+    <span class="kw">raise</span> <span class="cls">TypeError</span>(...)</pre>`,
+ opts:[
+   {t:'It raises a <code>TypeError</code> — only a <code>QWidget</code> or a <code>QGraphicsItem</code> is accepted.',correct:true,why:'Correct. Neither isinstance branch matches, so the explicit raise TypeError(...) fires, naming the wrong type.'},
+   {t:'It treats the string as a file path and loads it as the target image.',correct:false,why:'There is no path handling. A non-widget, non-item argument hits the TypeError branch.'},
+   {t:'It returns None and the comparison silently passes.',correct:false,why:'It raises rather than returning None — a misuse fails loudly, which is correct.'},
+   {t:'It grabs the active window as a fallback.',correct:false,why:'There is no fallback grab. The function strictly requires a QWidget or QGraphicsItem.'},
+ ]},
+
+{ch:'capture',type:'wr',
+ q:'Hardware blocks subclass <code>BaseBlock</code>. Why can\'t <code>compare_screenshot</code> capture a block with <code>block.grab()</code>, and what does it do instead?',
+ concepts:[
+   {label:'block is a QGraphicsItem not QWidget',terms:['qgraphicsitem','graphics item','not a qwidget','not qwidget']},
+   {label:'QGraphicsItem has no grab()/show()',terms:['no grab','no show','grab() does not','not have grab']},
+   {label:'rendered through QGraphicsScene.render',terms:['scene','render','qgraphicsscene','_capture_graphics_item']},
+ ],
+ model:'BaseBlock is a QGraphicsItem, not a QWidget. QGraphicsItem has no grab() and no show() — an item only exists inside a scene, it is not a standalone window. So _capture branches to _capture_graphics_item, which renders the item through a QGraphicsScene via scene.render(painter, ...).',
+},
+
+{ch:'capture',type:'wr',
+ q:`Read <code>_capture_graphics_item</code>:
+
+<pre class="snippet"><span class="kw">if</span> scene <span class="kw">is</span> <span class="pm">None</span>:
+    temp_scene = <span class="cls">QGraphicsScene</span>()
+    temp_scene.<span class="fn">addItem</span>(item)
+    scene = temp_scene
+...
+image.<span class="fn">fill</span>(<span class="cls">Qt</span>.<span class="cls">GlobalColor</span>.white)
+...
+<span class="kw">if</span> temp_scene <span class="kw">is</span> <span class="kw">not</span> <span class="pm">None</span>:
+    temp_scene.<span class="fn">removeItem</span>(item)</pre>
+
+Explain the temp-scene logic and why the background is filled white.`,
+ concepts:[
+   {label:'detached item needs a scene to render',terms:['detached','no scene','scene is none','needs a scene','only render']},
+   {label:'temp scene then remove to leave object untouched',terms:['remove','removeitem','untouched','restore','leave','side effect']},
+   {label:'white bg isolates block, not canvas grid',terms:['white','isolate','grid','just the block','alone','only the block']},
+ ],
+ model:'A QGraphicsItem can only be rendered through a scene. If item.scene() is None (a freshly constructed, detached block), there is nothing to render through, so the helper parks it in a throwaway QGraphicsScene, renders, then removeItem()s it so the caller object is left untouched (no side effects). The image is filled white so the golden captures just the block on a clean background — not the canvas grid or neighbouring blocks — keeping the block golden stable when the surrounding canvas changes.',
+},
+
+{ch:'capture',type:'mc',
+ q:'Which of these targets uses the <code>target.grab().toImage()</code> path, and which uses scene rendering?',
+ opts:[
+   {t:'MainWindow and <code>window.canvas_view</code> use grab(); each hardware block uses scene rendering.',correct:true,why:'Correct. MainWindow and CanvasView are QWidgets (grab path); blocks are QGraphicsItems (scene-render path).'},
+   {t:'Everything uses scene rendering — grab() is never used in these tests.',correct:false,why:'The main window and canvas view tests pass QWidgets, which take the grab() branch.'},
+   {t:'Everything uses grab() — blocks are wrapped in a QWidget proxy first.',correct:false,why:'Blocks are not wrapped in a proxy. They are QGraphicsItems and go through _capture_graphics_item.'},
+   {t:'Blocks use grab(); the window uses scene rendering.',correct:false,why:'Backwards. Widgets (window, canvas view) grab; items (blocks) render through a scene.'},
+ ]},
+
+// ── DETERMINISM ───────────────────────────────────────
+
+{ch:'determinism',type:'mc',
+ q:'Why is the default threshold 5 rather than 0?',
+ opts:[
+   {t:'Font hinting and antialiasing differ between machines/Qt builds; 0 would be flaky, 5 absorbs sub-pixel noise but still catches real changes.',correct:true,why:'Correct — this is the documented rationale. A small RMS from antialiasing stays under 5; a moved label or recoloured header exceeds it.'},
+   {t:'PNG compression loses up to 5 levels per channel.',correct:false,why:'PNG is lossless. The tolerance exists for cross-machine antialiasing/font rendering differences, not compression.'},
+   {t:'5 means 5% of pixels may differ.',correct:false,why:'It is an RMS magnitude on the 0-255 scale, not a percentage of differing pixels.'},
+   {t:'Qt requires a minimum threshold of 5 for offscreen rendering.',correct:false,why:'Qt imposes no such requirement. 5 is a project choice to balance flakiness vs sensitivity.'},
+ ]},
+
+{ch:'determinism',type:'wr',
+ q:'The multimeter paints <code>base + random.gauss(0, noise)</code>. Why does that break a golden test, and write the helper that fixes it (name + what it patches).',
+ concepts:[
+   {label:'random reading differs every run',terms:['random','every run','different','never match','noise']},
+   {label:'_freeze_live_readings replaces _get_reading',terms:['_freeze_live_readings','_get_reading','freeze','replace','monkeypatch','lambda']},
+   {label:'returns FROZEN_READING constant',terms:['frozen_reading','constant','1.2345678','fixed value']},
+   {label:'hasattr guard skips devices without it',terms:['hasattr','getattr','guard','if hasattr']},
+ ],
+ model:'A fresh Gaussian-noise reading renders differently on every capture, so it could never match a golden (RMS would blow past 5). _freeze_live_readings(block) reads block.device, and if it has _get_reading it replaces it with a lambda returning the constant FROZEN_READING = 1.2345678. The hasattr guard means devices without _get_reading are left untouched. The block then paints a stable value, making its golden reproducible.',
+},
+
+{ch:'determinism',type:'mc',
+ q:'In <code>test_canvas_with_psu_block</code>, why is the window resized to a fixed 1000x700 before screenshotting?',
+ opts:[
+   {t:'So the canvas viewport geometry — and thus the grid and fitted block — render identically on every machine.',correct:true,why:'Correct. A fixed window size makes the viewport (and everything laid out in it) deterministic across environments; a default size would vary.'},
+   {t:'1000x700 is the only size the offscreen platform supports.',correct:false,why:'Offscreen rendering supports arbitrary sizes. The fixed size is for determinism, not a platform limit.'},
+   {t:'To keep the golden PNG file under a size limit.',correct:false,why:'There is no file-size limit driving this. It is about reproducible geometry.'},
+   {t:'Because fit_all() only works at 1000x700.',correct:false,why:'fit_all() works at any size. The fixed window size is independent of fit_all and exists for deterministic layout.'},
+ ]},
+
+{ch:'determinism',type:'wr',
+ q:'A new block is auto-placed off-screen at the far top-left of the scene. If you screenshot the canvas view immediately, the golden is wrong. What call fixes it and why, and what kind of wait is used to know the block exists first?',
+ concepts:[
+   {label:'fit_all() brings block into view',terms:['fit_all','fit all','show all','into view']},
+   {label:'otherwise empty viewport/grid in golden',terms:['empty','off-screen','offscreen','empty grid','not visible']},
+   {label:'qtbot.waitUntil not time.sleep',terms:['waituntil','wait_until','waitUntil','not sleep','no sleep']},
+ ],
+ model:'window.canvas_view.fit_all() (the app own "show all" action) changes the view transform so the auto-placed off-screen block is brought into the viewport; without it the golden would just show an empty grid. To know the block exists before fitting, the test uses qtbot.waitUntil(lambda: len(window.canvas.blocks) == 1, timeout=...) — never time.sleep — which blocks until the condition is actually true. Then qapp.processEvents() flushes paint events before the grab.',
+},
+
+// ── GOLDEN WORKFLOW ───────────────────────────────────
+
+{ch:'workflow',type:'mc',
+ q:'You changed the UI on purpose and goldens no longer match. Which TWO commands both regenerate goldens (pick the option that lists correct ones)?',
+ opts:[
+   {t:'Delete the golden file and re-run that test (auto-recreate), OR run <code>UPDATE_GOLDEN=1 pytest tests/visual/</code>.',correct:true,why:'Correct. Both hit the `if update_golden or not golden_path.exists()` branch: deleting makes exists() false; the env var sets the flag for all goldens at once.'},
+   {t:'Run <code>pytest --update-goldens</code>, OR edit the PNG by hand.',correct:false,why:'There is no --update-goldens flag, and editing PNGs by hand is not the workflow. Use file deletion or UPDATE_GOLDEN=1.'},
+   {t:'Raise the threshold to 100, OR commit the diffs folder.',correct:false,why:'Raising the threshold hides regressions and diffs/ is git-ignored diagnostic output. Neither regenerates a golden.'},
+   {t:'Run <code>git checkout golden/</code>, OR delete <code>diffs/</code>.',correct:false,why:'git checkout restores the OLD golden, and deleting diffs/ just removes diagnostics. Neither produces a new golden.'},
+ ]},
+
+{ch:'workflow',type:'wr',
+ q:'Which directory is committed and which is git-ignored, and what role does each play? Why must you never commit a golden update without looking at it?',
+ concepts:[
+   {label:'golden/ committed = ground truth',terms:['golden','committed','ground truth','reference']},
+   {label:'diffs/ git-ignored = diagnostics',terms:['diffs','ignored','gitignore','diagnostic','artifact']},
+   {label:'blind update bakes in the regression',terms:['bake','blind','regression','silently','hide']},
+ ],
+ model:'tests/visual/golden/ is committed — it is the ground-truth reference. tests/visual/diffs/ is git-ignored — it holds per-run diagnostics (actual + amplified diff) that are regenerated on failure. You must eyeball any regenerated golden before committing because a blindly accepted golden silently bakes in whatever regression you were supposed to catch; the test then passes forever on the bug.',
+},
+
+// ── HEADLESS ──────────────────────────────────────────
+
+{ch:'headless',type:'mc',
+ q:'How do the GUI tests render with no <code>DISPLAY</code> on the EC2 runner?',
+ opts:[
+   {t:'Top-level conftest sets <code>QT_QPA_PLATFORM=offscreen</code> before Qt import; <code>pytest-xvfb</code> starts a virtual framebuffer automatically.',correct:true,why:'Correct. Offscreen rendering needs no X server, and pytest-xvfb (in requirements-dev.txt) spins up xvfb on EC2 — no manual DISPLAY or xvfb-run prefix.'},
+   {t:'Each test is launched with an explicit <code>xvfb-run</code> wrapper in the CI script.',correct:false,why:'You explicitly do NOT prefix with xvfb-run. pytest-xvfb handles it, and offscreen needs no X at all.'},
+   {t:'Qt is mocked, so no real rendering happens.',correct:false,why:'Qt really renders, just to an offscreen surface. Real pixels are essential for the golden comparison to mean anything.'},
+   {t:'A real X server is required; the runner runs a lightweight desktop.',correct:false,why:'No real display/desktop is needed. Offscreen + pytest-xvfb cover it headlessly.'},
+ ]},
+
+{ch:'headless',type:'wr',
+ q:'Why is <code>QT_QPA_PLATFORM=offscreen</code> set in the top-level <code>tests/conftest.py</code> instead of in the <code>qapp</code> fixture?',
+ concepts:[
+   {label:'Qt reads the var at import time',terms:['import','import time','before','reads','plugin']},
+   {label:'fixture runs after Qt already imported',terms:['fixture','too late','already imported','after']},
+   {label:'must set before any Qt import',terms:['before any qt','before qt import','ordering','order']},
+ ],
+ model:'Qt selects its platform plugin from QT_QPA_PLATFORM when its modules are first imported. By the time the qapp fixture runs, PyQt6 has already been imported at the top of the test modules/conftest, so setting it there would be too late. The top-level conftest.py sets it before any Qt import, guaranteeing the offscreen plugin is chosen. Same "set env before import" ordering rule applies to many Qt knobs.',
+},
+
+{ch:'headless',type:'mc',
+ q:'What does the session-scoped <code>qapp</code> fixture do?',
+ opts:[
+   {t:'Returns the existing <code>QApplication.instance()</code> if there is one, else creates a single new <code>QApplication([])</code> for the whole session.',correct:true,why:'Correct: app = QApplication.instance() or QApplication([]); yield app. You can only have one QApplication, and session scope shares it across all tests.'},
+   {t:'Creates a fresh QApplication for every test function for isolation.',correct:false,why:'It is session-scoped, not function-scoped — and you can only ever have one QApplication. It reuses a single instance.'},
+   {t:'Sets QT_QPA_PLATFORM and then creates the QApplication.',correct:false,why:'The env var is set in the top-level conftest before import, not in qapp. qapp only constructs/reuses the application.'},
+   {t:'Starts xvfb and tears it down after each test.',correct:false,why:'xvfb is handled by pytest-xvfb automatically, not by the qapp fixture.'},
+ ]},
+
+// ── TRAPS ─────────────────────────────────────────────
+
+{ch:'traps',type:'mc',
+ q:'A teammate "fixes" a flaky cross-platform visual test by setting <code>threshold=80</code> for that test. What is the real problem with this?',
+ opts:[
+   {t:'A threshold that large stops catching genuine layout/colour regressions — the test becomes a rubber stamp; the right fix is generating goldens on the target platform.',correct:true,why:'Correct. The doc says to generate goldens on the same platform the tests run on. Inflating the threshold to mask platform differences also masks real bugs.'},
+   {t:'Nothing — higher thresholds are always safer because tests fail less.',correct:false,why:'Failing less is exactly the danger: it stops detecting the regressions the test exists to catch.'},
+   {t:'threshold cannot exceed DEFAULT_THRESHOLD, so it would error.',correct:false,why:'threshold is just a parameter; any int is allowed. The problem is semantic, not an error.'},
+   {t:'It would change the RMS computation to a percentage.',correct:false,why:'threshold does not change how RMS is computed — only the pass/fail cutoff. The issue is that an inflated cutoff hides regressions.'},
+ ]},
+
+{ch:'traps',type:'wr',
+ q:'A CI run reports a visual failure but you cannot find <code>tests/visual/diffs/</code> in the repo. Why is it missing, and how do you actually inspect the failure?',
+ concepts:[
+   {label:'diffs/ is git-ignored, not in repo',terms:['git-ignored','gitignore','ignored','not committed','not in repo']},
+   {label:'retrieve from CI artifacts or reproduce locally',terms:['artifact','ci artifact','reproduce','locally','rerun']},
+   {label:'amplified diff shows where it changed',terms:['amplified','diff','10x','where','_diff']},
+ ],
+ model:'diffs/ is git-ignored because it is per-run diagnostic output (artifacts), not source — so it will never be committed. To inspect, pull the files from the CI job artifacts, or reproduce the failure locally and look in tests/visual/diffs/. The <name>_diff.png (amplified 10x) shows WHERE the change is; compare <name>_actual.png against the committed golden/<name>.png to see what changed.',
+},
+
+{ch:'traps',type:'mc',
+ q:'Why does <code>compare_screenshot</code> assert <code>actual.size == golden.size</code> before computing the RMS?',
+ opts:[
+   {t:'<code>ImageChops.difference</code> needs equal dimensions; a size change gets a clear dedicated error instead of a confusing crash.',correct:true,why:'Correct. The size assertion fires first with a "Screenshot size changed" message telling you to delete the golden and re-run if intentional.'},
+   {t:'To resize the actual image to match the golden before diffing.',correct:false,why:'It does not resize — it asserts equality and reports the mismatch. Resizing would mask real geometry changes.'},
+   {t:'Because larger images always fail the RMS check anyway.',correct:false,why:'Size and RMS are independent; the diff simply cannot be computed on mismatched sizes, hence the explicit guard.'},
+   {t:'To pick the correct threshold based on image area.',correct:false,why:'Threshold does not scale with area. The size assertion is purely a precondition for ImageChops.difference.'},
+ ]},
+
+{ch:'traps',type:'wr',
+ q:'Across the visual tests, what is the rule about waiting for the GUI, and which two qtbot helpers are used instead of sleeping? Name where each is used.',
+ concepts:[
+   {label:'never time.sleep',terms:['never sleep','no sleep','not time.sleep','avoid sleep']},
+   {label:'qtbot.waitUntil for the block to appear',terms:['waituntil','wait_until','waitUntil','blocks == 1']},
+   {label:'qtbot.waitExposed for the window',terms:['waitexposed','wait_exposed','waitExposed','exposed']},
+   {label:'processEvents flushes paint events',terms:['processevents','process_events','processEvents','flush']},
+ ],
